import React, { useState, useEffect } from 'react';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '../ui/card';
import { Badge } from '../ui/badge';
import { Button } from '../ui/button';
import {
  Phone,
  TrendingUp,
  Clock,
  Activity,
  PhoneCall,
  CheckCircle,
  XCircle,
  ArrowUpRight,
  MoreHorizontal
} from 'lucide-react';
import api from '../../services/api';
import { getErrorMessage } from '../../lib/utils';
import { useToast } from '../../hooks/use-toast';

const Dashboard = () => {
  const [stats, setStats] = useState(null);
  const [agents, setAgents] = useState([]);
  const [loading, setLoading] = useState(true);
  const { toast } = useToast();

  useEffect(() => {
    const fetchDashboardData = async () => {
      try {
        const [statsRes, agentsRes] = await Promise.all([
          api.calls.getDashboardStats(),
          api.agents.getAgents()
        ]);
        setStats(statsRes.data);
        setAgents(agentsRes.data);
      } catch (error) {
        console.error("Failed to fetch dashboard data:", error);
        toast({
          title: "Error fetching dashboard data",
          description: getErrorMessage(error),
          variant: "destructive"
        });
      } finally {
        setLoading(false);
      }
    };

    fetchDashboardData();
  }, [toast]);

  const StatCard = ({ title, value, subtitle, icon: Icon, trend, color = "emerald" }) => (
    <Card className="relative overflow-hidden">
      <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
        <CardTitle className="text-sm font-medium text-gray-600">{title}</CardTitle>
        <Icon className={`w-4 h-4 text-${color}-600`} />
      </CardHeader>
      <CardContent>
        <div className="text-2xl font-bold text-gray-900">{value}</div>
        {subtitle && (
          <p className="text-xs text-gray-500 mt-1">
            {trend !== undefined && (
              <span className={`inline-flex items-center ${trend >= 0 ? 'text-emerald-600' : 'text-red-600'}`}>
                <ArrowUpRight className={`w-3 h-3 mr-1 ${trend < 0 ? 'rotate-90' : ''}`} />
                {Math.abs(trend)}%
              </span>
            )}
            {subtitle}
          </p>
        )}
      </CardContent>
    </Card>
  );

  const CallRow = ({ call, agent }) => {
    const getStatusColor = (status) => {
      switch (status) {
        case 'completed': return 'text-emerald-600 bg-emerald-50';
        case 'in_progress': return 'text-blue-600 bg-blue-50';
        case 'failed': return 'text-red-600 bg-red-50';
        default: return 'text-gray-600 bg-gray-50';
      }
    };

    const formatDuration = (seconds) => {
      if (!seconds) return '--';
      const mins = Math.floor(seconds / 60);
      const secs = seconds % 60;
      return `${mins}:${secs.toString().padStart(2, '0')}`;
    };

    return (
      <div className="flex items-center justify-between p-4 border-b border-gray-100 last:border-b-0">
        <div className="flex items-center space-x-3">
          <div className="w-10 h-10 bg-gray-100 rounded-full flex items-center justify-center">
            <Phone className="w-4 h-4 text-gray-600" />
          </div>
          <div>
            <p className="text-sm font-medium text-gray-900">{call.from_number}</p>
            <p className="text-xs text-gray-500">{agent?.name || 'AI Assistant'}</p>
          </div>
        </div>
        <div className="text-right">
          <Badge
            variant="secondary"
            className={`text-xs mb-1 ${getStatusColor(call.status)}`}
          >
            {call.status.replace('_', ' ')}
          </Badge>
          <p className="text-xs text-gray-500">{formatDuration(call.duration_seconds)}</p>
        </div>
      </div>
    );
  };

  if (loading) {
    return <div className="p-6 flex items-center justify-center h-full">Loading dashboard...</div>;
  }

  const dashboardStats = stats || {
    totalCalls: 0,
    successRate: 0,
    avgCallDuration: "0:00",
    activeCalls: 0,
    recentCalls: [],
    monthlyCallVolume: []
  };

  const activeAgents = agents.filter(agent => agent.is_active);

  return (
    <div className="p-6 space-y-6">
      {/* Header */}
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between">
        <div>
          <h1 className="text-2xl font-bold text-gray-900">Dashboard</h1>
          <p className="text-gray-500 mt-1">Monitor your AI agents and call performance</p>
        </div>
        <div className="flex items-center space-x-3 mt-4 sm:mt-0">
          <Button variant="outline" size="sm">
            <Activity className="w-4 h-4 mr-2" />
            Live View
          </Button>
          <Button size="sm" className="bg-emerald-600 hover:bg-emerald-700">
            <Phone className="w-4 h-4 mr-2" />
            Start Call
          </Button>
        </div>
      </div>

      {/* Stats Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        <StatCard
          title="Total Calls Today"
          value={dashboardStats.totalCalls.toLocaleString()}
          subtitle="lifetime total"
          icon={PhoneCall}
        />
        <StatCard
          title="Success Rate"
          value={`${dashboardStats.successRate}%`}
          subtitle="all time"
          icon={CheckCircle}
          color="emerald"
        />
        <StatCard
          title="Avg Call Duration"
          value={dashboardStats.avgCallDuration}
          subtitle="across agents"
          icon={Clock}
          color="blue"
        />
        <StatCard
          title="Active Agents"
          value={activeAgents.length}
          subtitle="ready to call"
          icon={Activity}
          color="orange"
        />
      </div>

      {/* Main Content Grid */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        <Card className="lg:col-span-2">
          <CardHeader>
            <CardTitle className="text-lg">Call Volume Trends</CardTitle>
            <CardDescription>Activity overview</CardDescription>
          </CardHeader>
          <CardContent>
            <div className="h-64 bg-gradient-to-br from-emerald-50 to-teal-50 rounded-lg flex items-center justify-center">
              <div className="text-center">
                <TrendingUp className="w-12 h-12 text-emerald-600 mx-auto mb-2" />
                <p className="text-gray-600">Performance insights</p>
                <p className="text-sm text-gray-500 mt-1">Real-time data enabled</p>
              </div>
            </div>
          </CardContent>
        </Card>

        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0">
            <div>
              <CardTitle className="text-lg">Recent Calls</CardTitle>
              <CardDescription>Latest call activity</CardDescription>
            </div>
            <Button variant="ghost" size="sm">
              <MoreHorizontal className="w-4 h-4" />
            </Button>
          </CardHeader>
          <CardContent className="p-0">
            <div className="max-h-80 overflow-y-auto">
              {dashboardStats.recentCalls.length > 0 ? (
                dashboardStats.recentCalls.map((call) => {
                  const agent = agents.find(a => a.id === call.agent_id);
                  return (
                    <CallRow key={call.id} call={call} agent={agent} />
                  );
                })
              ) : (
                <div className="p-8 text-center text-gray-500">No recent calls found</div>
              )}
            </div>
          </CardContent>
        </Card>
      </div>

      {/* Active Agents List */}
      <Card>
        <CardHeader>
          <div className="flex items-center justify-between">
            <div>
              <CardTitle className="text-lg">My AI Agents</CardTitle>
              <CardDescription>Configure and manage your agents</CardDescription>
            </div>
            <Button variant="outline" size="sm" asChild>
              <a href="/agents">View All</a>
            </Button>
          </div>
        </CardHeader>
        <CardContent>
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
            {agents.length > 0 ? (
              agents.slice(0, 3).map((agent) => (
                <div key={agent.id} className="p-4 border border-gray-200 rounded-lg">
                  <div className="flex items-center justify-between mb-2">
                    <h3 className="font-medium text-gray-900">{agent.name}</h3>
                    <Badge
                      variant="secondary"
                      className={agent.is_active ? 'bg-emerald-50 text-emerald-700' : 'bg-gray-50 text-gray-700'}
                    >
                      {agent.is_active ? 'Active' : 'Inactive'}
                    </Badge>
                  </div>
                  <p className="text-sm text-gray-600 mb-2 line-clamp-2">{agent.description || "No description provided"}</p>
                  <div className="flex items-center text-xs text-gray-500">
                    <Phone className="w-3 h-3 mr-1" />
                    {agent.signalwire_phone_number || 'No number assigned'}
                  </div>
                </div>
              ))
            ) : (
              <div className="col-span-3 p-8 text-center border-2 border-dashed border-gray-100 rounded-lg">
                <p className="text-gray-500">You haven't created any agents yet.</p>
                <Button variant="link" asChild className="mt-2">
                  <a href="/agents/new">Create your first agent</a>
                </Button>
              </div>
            )}
          </div>
        </CardContent>
      </Card>
    </div>
  );
};

export default Dashboard;
